tool_use_result.content:
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --brand: #15295A;
  --accent: #00B4D8;
  --accent-dark: #0077B6;
  --green: #6CC24A;
  --gray-dark: #3C424B;
  --gray-mid: #8892A0;
  --gray-light: #B0B8C4;
  --white: #FFFFFF;
  --off-white: #E8ECF1;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 4px 24px rgba(0,0,0,0.3);
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--navy);
  color: var(--off-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--white); }

img { max-width: 100%; display: block; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section--alt { background: var(--navy-mid); }
.text-center { text-align: center; }
.text-accent { color: var(--accent); }
.text-green { color: var(--green); }

.label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}

h1, h2, h3, h4 { font-weight: 700; line-height: 1.2; color: var(--white); }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); margin-bottom: 16px; }
h3 { font-size: 1.25rem; margin-bottom: 8px; }
p { color: var(--gray-light); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}

.btn--primary {
  background: var(--accent);
  color: var(--navy);
}
.btn--primary:hover { background: #33C9E8; color: var(--navy); }

.btn--outline {
  background: transparent;
  color: var(--accent);
  border: 2px solid var(--accent);
}
.btn--outline:hover { background: var(--accent); color: var(--navy); }

.btn--green { background: var(--green); color: var(--navy); }
.btn--green:hover { background: #7DD45B; color: var(--navy); }

.btn--sm { padding: 10px 20px; font-size: 0.85rem; }

/* ===== HEADER / NAV ===== */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.header__logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
}
.header__logo span { color: var(--accent); }

.nav { display: flex; align-items: center; gap: 32px; }

.nav__link {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-light);
  position: relative;
}
.nav__link:hover { color: var(--white); }

/* Dropdown */
.nav__dropdown { position: relative; }
.nav__dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-light);
  cursor: pointer;
  background: none;
  border: none;
  font-family: var(--font);
}
.nav__dropdown-toggle:hover { color: var(--white); }
.nav__dropdown-toggle svg { width: 12px; height: 12px; transition: transform var(--transition); }

.nav__dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  padding: 8px 0;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  box-shadow: var(--shadow);
}
.nav__dropdown:hover .nav__dropdown-menu { opacity: 1; visibility: visible; }
.nav__dropdown:hover .nav__dropdown-toggle svg { transform: rotate(180deg); }

.nav__dropdown-item {
  display: block;
  padding: 10px 20px;
  font-size: 0.85rem;
  color: var(--gray-light);
  transition: all var(--transition);
}
.nav__dropdown-item:hover { background: var(--navy-light); color: var(--white); }

/* Mobile nav toggle */
.nav__toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }
.nav__toggle span { display: block; width: 24px; height: 2px; background: var(--white); margin: 5px 0; transition: var(--transition); }

/* ===== HERO ===== */
.hero {
  padding: 140px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -40%; right: -20%;
  width: 800px; height: 800px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content { max-width: 720px; position: relative; z-index: 1; }
.hero__title { margin-bottom: 20px; }
.hero__subtitle { font-size: 1.15rem; margin-bottom: 32px; color: var(--gray-light); line-height: 1.7; }
.hero__actions { display: flex; gap: 16px; flex-wrap: wrap; }

.hero--centered { text-align: center; }
.hero--centered .hero__content { max-width: 800px; margin: 0 auto; }
.hero--centered .hero__actions { justify-content: center; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  padding: 40px 0;
  background: linear-gradient(135deg, var(--brand) 0%, var(--navy-light) 100%);
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.featured-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.featured-banner__text h3 { font-size: 1.1rem; }
.featured-banner__text p { font-size: 0.9rem; color: var(--gray-mid); }
.featured-banner__badge {
  display: inline-block;
  background: var(--accent);
  color: var(--navy);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}

/* ===== USE CASES ===== */
.use-cases__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.use-case-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all var(--transition);
  cursor: pointer;
}
.use-case-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0,180,216,0.12);
}

.use-case-card__icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--accent);
  font-size: 1.4rem;
}

.use-case-card h3 { font-size: 1.05rem; margin-bottom: 8px; }
.use-case-card p { font-size: 0.88rem; color: var(--gray-mid); line-height: 1.6; }

/* ===== TABS ===== */
.tabs { margin-top: 32px; }

.tabs__nav {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid rgba(255,255,255,0.08);
  margin-bottom: 32px;
  overflow-x: auto;
}

.tabs__tab {
  padding: 12px 24px;
  font-family: var(--font);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-mid);
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}
.tabs__tab:hover { color: var(--white); }
.tabs__tab.active { color: var(--accent); border-bottom-color: var(--accent); }

.tabs__panel { display: none; }
.tabs__panel.active { display: block; animation: fadeIn 0.3s ease; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== PLATFORM DIAGRAM ===== */
.diagram {
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
  margin-top: 48px;
}

.diagram__pillar {
  flex: 1;
  min-width: 280px;
  max-width: 360px;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}
.diagram__pillar:hover { border-color: var(--accent); }

.diagram__pillar-icon {
  width: 64px; height: 64px;
  margin: 0 auto 16px;
  background: rgba(0,180,216,0.12);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.6rem;
}

.diagram__pillar h3 { margin-bottom: 8px; }
.diagram__pillar p { font-size: 0.88rem; color: var(--gray-mid); }

.diagram__connector {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.5rem;
  min-width: 40px;
}

/* ===== STATS ===== */
.stats__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.stat {
  text-align: center;
}

.stat__circle {
  width: 160px; height: 160px;
  margin: 0 auto 20px;
  position: relative;
}

.stat__circle svg {
  width: 100%; height: 100%;
  transform: rotate(-90deg);
}

.stat__circle-bg {
  fill: none;
  stroke: rgba(255,255,255,0.06);
  stroke-width: 8;
}

.stat__circle-fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 440;
  stroke-dashoffset: 440;
  transition: stroke-dashoffset 1.5s ease;
}

.stat__circle-value {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--white);
}

.stat p { font-size: 0.9rem; color: var(--gray-mid); max-width: 200px; margin: 0 auto; }

/* ===== BENEFITS ===== */
.benefits__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  margin-top: 40px;
}

.benefit-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
  transition: all var(--transition);
}
.benefit-card:hover { border-color: var(--accent); transform: translateY(-2px); }

.benefit-card__icon {
  width: 48px; height: 48px;
  margin: 0 auto 14px;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.2rem;
}

.benefit-card h3 { font-size: 1rem; margin-bottom: 6px; }
.benefit-card p { font-size: 0.85rem; color: var(--gray-mid); }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline { margin-top: 40px; }

.timeline__item {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  padding: 24px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline__item:last-child { border-bottom: none; }

.timeline__duration {
  min-width: 120px;
  text-align: right;
}
.timeline__duration strong {
  display: block;
  font-size: 1.3rem;
  color: var(--accent);
}

.timeline__bar-wrap { flex: 1; }
.timeline__bar-track {
  width: 100%;
  height: 8px;
  background: rgba(255,255,255,0.06);
  border-radius: 4px;
  margin: 8px 0;
}
.timeline__bar-fill {
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-dark));
  transition: width 1s ease;
}

.timeline__label { font-size: 0.9rem; color: var(--gray-light); }

/* ===== ACCORDION ===== */
.accordion { margin-top: 40px; }

.accordion__item {
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius);
  margin-bottom: 8px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion__item.open { border-color: var(--accent); }

.accordion__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  background: var(--navy-mid);
  cursor: pointer;
  border: none;
  width: 100%;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  color: var(--white);
  text-align: left;
  transition: background var(--transition);
}
.accordion__header:hover { background: var(--navy-light); }

.accordion__icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  transition: transform var(--transition);
  font-size: 1.2rem;
  flex-shrink: 0;
}
.accordion__item.open .accordion__icon { transform: rotate(45deg); }

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
  background: var(--navy-mid);
}
.accordion__item.open .accordion__body { max-height: 300px; }

.accordion__content { padding: 0 24px 20px; color: var(--gray-light); font-size: 0.92rem; line-height: 1.7; }

/* ===== TESTIMONIAL CAROUSEL ===== */
.carousel { margin-top: 40px; position: relative; overflow: hidden; }

.carousel__track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel__slide {
  min-width: 100%;
  padding: 0 16px;
}

.testimonial-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 40px;
  position: relative;
}

.testimonial-card__quote {
  font-size: 1.1rem;
  font-style: italic;
  color: var(--off-white);
  line-height: 1.7;
  margin-bottom: 20px;
}

.testimonial-card__quote::before {
  content: '\201C';
  font-size: 3rem;
  color: var(--accent);
  line-height: 0;
  vertical-align: -0.4em;
  margin-right: 4px;
}

.testimonial-card__author { font-size: 0.9rem; color: var(--gray-mid); }

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel__dot.active { background: var(--accent); transform: scale(1.2); }

/* ===== SECURITY FEATURES ===== */
.security-features { margin-top: 40px; }

.security-feature {
  display: flex;
  gap: 20px;
  padding: 28px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  align-items: flex-start;
}
.security-feature:last-child { border-bottom: none; }

.security-feature__icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.2rem;
  flex-shrink: 0;
}

.security-feature__text h3 { font-size: 1.05rem; margin-bottom: 4px; }
.security-feature__text p { font-size: 0.9rem; color: var(--gray-mid); line-height: 1.6; }

/* ===== INTEGRATION TABS ===== */
.integration-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: start;
}

.integration-panel__visual {
  background: var(--navy-light);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.integration-panel__content h3 { margin-bottom: 12px; }
.integration-panel__content p { margin-bottom: 16px; line-height: 1.7; }

/* ===== ETL BENEFITS ===== */
.etl-benefits__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.etl-benefit {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  align-items: flex-start;
  transition: all var(--transition);
}
.etl-benefit:hover { border-color: var(--green); }

.etl-benefit__check {
  width: 28px; height: 28px;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  font-size: 0.85rem;
  flex-shrink: 0;
}

.etl-benefit h3 { font-size: 0.95rem; margin-bottom: 4px; }
.etl-benefit p { font-size: 0.85rem; color: var(--gray-mid); }

/* ===== DEMO FORM ===== */
.demo-form { max-width: 680px; margin: 0 auto; }

.demo-form__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 32px;
}

.form-group { display: flex; flex-direction: column; }
.form-group--full { grid-column: 1 / -1; }

.form-group label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gray-light);
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: var(--navy-light);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius);
  color: var(--white);
  font-family: var(--font);
  font-size: 0.95rem;
  transition: border-color var(--transition);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent);
}

.form-group textarea { resize: vertical; min-height: 100px; }

.form-group .error-msg {
  font-size: 0.78rem;
  color: #E74C3C;
  margin-top: 4px;
  display: none;
}
.form-group.has-error .error-msg { display: block; }
.form-group.has-error input,
.form-group.has-error select,
.form-group.has-error textarea { border-color: #E74C3C; }

.demo-form__submit { margin-top: 28px; text-align: center; }

/* ===== SUPPORT CONTACT ===== */
.support-regions {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}

.support-region {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
}
.support-region h3 { font-size: 1rem; margin-bottom: 8px; }
.support-region p { font-size: 0.88rem; color: var(--gray-mid); }

/* ===== COMPANY CULTURE ===== */
.culture {
  background: linear-gradient(135deg, var(--brand) 0%, var(--navy) 100%);
}

.culture__inner {
  display: flex;
  align-items: center;
  gap: 48px;
}

.culture__content { flex: 1; }
.culture__content p { font-size: 1rem; line-height: 1.7; margin-bottom: 24px; }

.culture__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.culture__number {
  font-size: 6rem;
  font-weight: 900;
  color: var(--accent);
  line-height: 1;
  opacity: 0.2;
}
.culture__number span { font-size: 1.5rem; display: block; font-weight: 600; opacity: 1; color: var(--gray-light); }

/* ===== RENEWABLES CTA ===== */
.renewables {
  background: linear-gradient(135deg, #0a2a1a 0%, var(--navy) 100%);
}

.renewables__inner {
  display: flex;
  align-items: center;
  gap: 48px;
}

.renewables__content { flex: 1; }
.renewables__content p { font-size: 1rem; line-height: 1.7; margin-bottom: 24px; }

.renewables__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== COMPLIANCE CTA ===== */
.compliance-cta {
  text-align: center;
  padding: 60px 0;
}

.compliance-cta h2 { margin-bottom: 12px; }
.compliance-cta p { max-width: 600px; margin: 0 auto 28px; }

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0;
  margin-top: 48px;
  flex-wrap: wrap;
}

.lifecycle-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 20px 16px;
  position: relative;
  min-width: 120px;
}

.lifecycle-step__circle {
  width: 72px; height: 72px;
  border-radius: 50%;
  background: rgba(0,180,216,0.12);
  border: 2px solid var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 12px;
  transition: all var(--transition);
}
.lifecycle-step:hover .lifecycle-step__circle { background: var(--accent); color: var(--navy); }

.lifecycle-step__label { font-size: 0.82rem; font-weight: 600; color: var(--gray-light); }

.lifecycle-arrow {
  color: var(--accent);
  font-size: 1.5rem;
  padding: 0 8px;
  opacity: 0.5;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: var(--navy-mid);
  border-top: 1px solid rgba(255,255,255,0.08);
  padding: 20px 0;
  z-index: 2000;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { transform: translateY(100%); }

.cookie-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner__text { font-size: 0.88rem; color: var(--gray-light); }
.cookie-banner__actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ===== FOOTER ===== */
.footer {
  background: var(--brand);
  padding: 60px 0 30px;
  border-top: 1px solid rgba(255,255,255,0.05);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 32px;
}

.footer__brand p { font-size: 0.85rem; color: var(--gray-mid); margin-top: 12px; line-height: 1.6; }

.footer__col h4 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-light);
  margin-bottom: 16px;
}

.footer__link {
  display: block;
  font-size: 0.85rem;
  color: var(--gray-mid);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer__link:hover { color: var(--accent); }

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.06);
  font-size: 0.8rem;
  color: var(--gray-mid);
}

.footer__login-links { display: flex; gap: 20px; }

/* ===== SVG DIAGRAM ICONS ===== */
.icon-svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .use-cases__grid { grid-template-columns: repeat(2, 1fr); }
  .stats__grid { grid-template-columns: repeat(3, 1fr); gap: 20px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .integration-panel { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .section { padding: 56px 0; }
  .hero { padding: 110px 0 56px; }

  .nav { display: none; }
  .nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px; left: 0; right: 0;
    background: var(--navy-mid);
    padding: 20px 24px;
    gap: 16px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
  }
  .nav__toggle { display: block; }

  .nav__dropdown-menu {
    position: static;
    transform: none;
    opacity: 1;
    visibility: visible;
    box-shadow: none;
    border: none;
    padding-left: 16px;
  }

  .use-cases__grid { grid-template-columns: 1fr; }
  .stats__grid { grid-template-columns: 1fr; gap: 32px; }
  .benefits__grid { grid-template-columns: repeat(2, 1fr); }
  .etl-benefits__grid { grid-template-columns: 1fr; }
  .support-regions { grid-template-columns: 1fr; }

  .featured-banner__inner { flex-direction: column; text-align: center; }

  .culture__inner, .renewables__inner { flex-direction: column; text-align: center; }

  .demo-form__grid { grid-template-columns: 1fr; }

  .footer__grid { grid-template-columns: repeat(2, 1fr); }

  .diagram { flex-direction: column; align-items: center; }
  .diagram__connector { transform: rotate(90deg); }

  .lifecycle-diagram { flex-direction: column; }
  .lifecycle-arrow { transform: rotate(90deg); }

  .cookie-banner__inner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .benefits__grid { grid-template-columns: 1fr; }
  .footer__grid { grid-template-columns: 1fr; }
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; justify-content: center; }
}

/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --brand: #15295A;
  --accent: #00B4D8;
  --accent-dark: #0077B6;
  --green: #6CC24A;
  --gray-dark: #3C424B;
  --gray-mid: #8892A0;
  --gray-light: #B0B8C4;
  --white: #FFFFFF;
  --off-white: #E8ECF1;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 4px 24px rgba(0,0,0,0.3);
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--navy);
  color: var(--off-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--white); }

img { max-width: 100%; display: block; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section--alt { background: var(--navy-mid); }
.text-center { text-align: center; }
.text-accent { color: var(--accent); }
.text-green { color: var(--green); }

.label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}

h1, h2, h3, h4 { font-weight: 700; line-height: 1.2; color: var(--white); }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); margin-bottom: 16px; }
h3 { font-size: 1.25rem; margin-bottom: 8px; }
p { color: var(--gray-light); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}

.btn--primary {
  background: var(--accent);
  color: var(--navy);
}
.btn--primary:hover { background: #33C9E8; color: var(--navy); }

.btn--outline {
  background: transparent;
  color: var(--accent);
  border: 2px solid var(--accent);
}
.btn--outline:hover { background: var(--accent); color: var(--navy); }

.btn--green { background: var(--green); color: var(--navy); }
.btn--green:hover { background: #7DD45B; color: var(--navy); }

.btn--sm { padding: 10px 20px; font-size: 0.85rem; }

/* ===== HEADER / NAV ===== */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.header__logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
}
.header__logo span { color: var(--accent); }

.nav { display: flex; align-items: center; gap: 32px; }

.nav__link {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-light);
  position: relative;
}
.nav__link:hover { color: var(--white); }

/* Dropdown */
.nav__dropdown { position: relative; }
.nav__dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-light);
  cursor: pointer;
  background: none;
  border: none;
  font-family: var(--font);
}
.nav__dropdown-toggle:hover { color: var(--white); }
.nav__dropdown-toggle svg { width: 12px; height: 12px; transition: transform var(--transition); }

.nav__dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  padding: 8px 0;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  box-shadow: var(--shadow);
}
.nav__dropdown:hover .nav__dropdown-menu { opacity: 1; visibility: visible; }
.nav__dropdown:hover .nav__dropdown-toggle svg { transform: rotate(180deg); }

.nav__dropdown-item {
  display: block;
  padding: 10px 20px;
  font-size: 0.85rem;
  color: var(--gray-light);
  transition: all var(--transition);
}
.nav__dropdown-item:hover { background: var(--navy-light); color: var(--white); }

/* Mobile nav toggle */
.nav__toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }
.nav__toggle span { display: block; width: 24px; height: 2px; background: var(--white); margin: 5px 0; transition: var(--transition); }

/* ===== HERO ===== */
.hero {
  padding: 140px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -40%; right: -20%;
  width: 800px; height: 800px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content { max-width: 720px; position: relative; z-index: 1; }
.hero__title { margin-bottom: 20px; }
.hero__subtitle { font-size: 1.15rem; margin-bottom: 32px; color: var(--gray-light); line-height: 1.7; }
.hero__actions { display: flex; gap: 16px; flex-wrap: wrap; }

.hero--centered { text-align: center; }
.hero--centered .hero__content { max-width: 800px; margin: 0 auto; }
.hero--centered .hero__actions { justify-content: center; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  padding: 40px 0;
  background: linear-gradient(135deg, var(--brand) 0%, var(--navy-light) 100%);
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.featured-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.featured-banner__text h3 { font-size: 1.1rem; }
.featured-banner__text p { font-size: 0.9rem; color: var(--gray-mid); }
.featured-banner__badge {
  display: inline-block;
  background: var(--accent);
  color: var(--navy);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}

/* ===== USE CASES ===== */
.use-cases__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.use-case-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all var(--transition);
  cursor: pointer;
}
.use-case-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0,180,216,0.12);
}

.use-case-card__icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--accent);
  font-size: 1.4rem;
}

.use-case-card h3 { font-size: 1.05rem; margin-bottom: 8px; }
.use-case-card p { font-size: 0.88rem; color: var(--gray-mid); line-height: 1.6; }

/* ===== TABS ===== */
.tabs { margin-top: 32px; }

.tabs__nav {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid rgba(255,255,255,0.08);
  margin-bottom: 32px;
  overflow-x: auto;
}

.tabs__tab {
  padding: 12px 24px;
  font-family: var(--font);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-mid);
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}
.tabs__tab:hover { color: var(--white); }
.tabs__tab.active { color: var(--accent); border-bottom-color: var(--accent); }

.tabs__panel { display: none; }
.tabs__panel.active { display: block; animation: fadeIn 0.3s ease; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== PLATFORM DIAGRAM ===== */
.diagram {
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
  margin-top: 48px;
}

.diagram__pillar {
  flex: 1;
  min-width: 280px;
  max-width: 360px;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}
.diagram__pillar:hover { border-color: var(--accent); }

.diagram__pillar-icon {
  width: 64px; height: 64px;
  margin: 0 auto 16px;
  background: rgba(0,180,216,0.12);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.6rem;
}

.diagram__pillar h3 { margin-bottom: 8px; }
.diagram__pillar p { font-size: 0.88rem; color: var(--gray-mid); }

.diagram__connector {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.5rem;
  min-width: 40px;
}

/* ===== STATS ===== */
.stats__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.stat {
  text-align: center;
}

.stat__circle {
  width: 160px; height: 160px;
  margin: 0 auto 20px;
  position: relative;
}

.stat__circle svg {
  width: 100%; height: 100%;
  transform: rotate(-90deg);
}

.stat__circle-bg {
  fill: none;
  stroke: rgba(255,255,255,0.06);
  stroke-width: 8;
}

.stat__circle-fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 440;
  stroke-dashoffset: 440;
  transition: stroke-dashoffset 1.5s ease;
}

.stat__circle-value {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--white);
}

.stat p { font-size: 0.9rem; color: var(--gray-mid); max-width: 200px; margin: 0 auto; }

/* ===== BENEFITS ===== */
.benefits__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  margin-top: 40px;
}

.benefit-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
  transition: all var(--transition);
}
.benefit-card:hover { border-color: var(--accent); transform: translateY(-2px); }

.benefit-card__icon {
  width: 48px; height: 48px;
  margin: 0 auto 14px;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.2rem;
}

.benefit-card h3 { font-size: 1rem; margin-bottom: 6px; }
.benefit-card p { font-size: 0.85rem; color: var(--gray-mid); }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline { margin-top: 40px; }

.timeline__item {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  padding: 24px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline__item:last-child { border-bottom: none; }

.timeline__duration {
  min-width: 120px;
  text-align: right;
}
.timeline__duration strong {
  display: block;
  font-size: 1.3rem;
  color: var(--accent);
}

.timeline__bar-wrap { flex: 1; }
.timeline__bar-track {
  width: 100%;
  height: 8px;
  background: rgba(255,255,255,0.06);
  border-radius: 4px;
  margin: 8px 0;
}
.timeline__bar-fill {
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-dark));
  transition: width 1s ease;
}

.timeline__label { font-size: 0.9rem; color: var(--gray-light); }

/* ===== ACCORDION ===== */
.accordion { margin-top: 40px; }

.accordion__item {
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius);
  margin-bottom: 8px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion__item.open { border-color: var(--accent); }

.accordion__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  background: var(--navy-mid);
  cursor: pointer;
  border: none;
  width: 100%;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  color: var(--white);
  text-align: left;
  transition: background var(--transition);
}
.accordion__header:hover { background: var(--navy-light); }

.accordion__icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  transition: transform var(--transition);
  font-size: 1.2rem;
  flex-shrink: 0;
}
.accordion__item.open .accordion__icon { transform: rotate(45deg); }

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
  background: var(--navy-mid);
}
.accordion__item.open .accordion__body { max-height: 300px; }

.accordion__content { padding: 0 24px 20px; color: var(--gray-light); font-size: 0.92rem; line-height: 1.7; }

/* ===== TESTIMONIAL CAROUSEL ===== */
.carousel { margin-top: 40px; position: relative; overflow: hidden; }

.carousel__track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel__slide {
  min-width: 100%;
  padding: 0 16px;
}

.testimonial-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 40px;
  position: relative;
}

.testimonial-card__quote {
  font-size: 1.1rem;
  font-style: italic;
  color: var(--off-white);
  line-height: 1.7;
  margin-bottom: 20px;
}

.testimonial-card__quote::before {
  content: '\201C';
  font-size: 3rem;
  color: var(--accent);
  line-height: 0;
  vertical-align: -0.4em;
  margin-right: 4px;
}

.testimonial-card__author { font-size: 0.9rem; color: var(--gray-mid); }

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel__dot.active { background: var(--accent); transform: scale(1.2); }

/* ===== SECURITY FEATURES ===== */
.security-features { margin-top: 40px; }

.security-feature {
  display: flex;
  gap: 20px;
  padding: 28px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  align-items: flex-start;
}
.security-feature:last-child { border-bottom: none; }

.security-feature__icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.2rem;
  flex-shrink: 0;
}

.security-feature__text h3 { font-size: 1.05rem; margin-bottom: 4px; }
.security-feature__text p { font-size: 0.9rem; color: var(--gray-mid); line-height: 1.6; }

/* ===== INTEGRATION TABS ===== */
.integration-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: start;
}

.integration-panel__visual {
  background: var(--navy-light);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.integration-panel__content h3 { margin-bottom: 12px; }
.integration-panel__content p { margin-bottom: 16px; line-height: 1.7; }

/* ===== ETL BENEFITS ===== */
.etl-benefits__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.etl-benefit {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  align-items: flex-start;
  transition: all var(--transition);
}
.etl-benefit:hover { border-color: var(--green); }

.etl-benefit__check {
  width: 28px; height: 28px;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  font-size: 0.85rem;
  flex-shrink: 0;
}

.etl-benefit h3 { font-size: 0.95rem; margin-bottom: 4px; }
.etl-benefit p { font-size: 0.85rem; color: var(--gray-mid); }

/* ===== DEMO FORM ===== */
.demo-form { max-width: 680px; margin: 0 auto; }

.demo-form__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 32px;
}

.form-group { display: flex; flex-direction: column; }
.form-group--full { grid-column: 1 / -1; }

.form-group label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gray-light);
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: var(--navy-light);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius);
  color: var(--white);
  font-family: var(--font);
  font-size: 0.95rem;
  transition: border-color var(--transition);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent);
}

.form-group textarea { resize: vertical; min-height: 100px; }

.form-group .error-msg {
  font-size: 0.78rem;
  color: #E74C3C;
  margin-top: 4px;
  display: none;
}
.form-group.has-error .error-msg { display: block; }
.form-group.has-error input,
.form-group.has-error select,
.form-group.has-error textarea { border-color: #E74C3C; }

.demo-form__submit { margin-top: 28px; text-align: center; }

/* ===== SUPPORT CONTACT ===== */
.support-regions {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}

.support-region {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
}
.support-region h3 { font-size: 1rem; margin-bottom: 8px; }
.support-region p { font-size: 0.88rem; color: var(--gray-mid); }

/* ===== COMPANY CULTURE ===== */
.culture {
  background: linear-gradient(135deg, var(--brand) 0%, var(--navy) 100%);
}

.culture__inner {
  display: flex;
  align-items: center;
  gap: 48px;
}

.culture__content { flex: 1; }
.culture__content p { font-size: 1rem; line-height: 1.7; margin-bottom: 24px; }

.culture__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.culture__number {
  font-size: 6rem;
  font-weight: 900;
  color: var(--accent);
  line-height: 1;
  opacity: 0.2;
}
.culture__number span { font-size: 1.5rem; display: block; font-weight: 600; opacity: 1; color: var(--gray-light); }

/* ===== RENEWABLES CTA ===== */
.renewables {
  background: linear-gradient(135deg, #0a2a1a 0%, var(--navy) 100%);
}

.renewables__inner {
  display: flex;
  align-items: center;
  gap: 48px;
}

.renewables__content { flex: 1; }
.renewables__content p { font-size: 1rem; line-height: 1.7; margin-bottom: 24px; }

.renewables__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== COMPLIANCE CTA ===== */
.compliance-cta {
  text-align: center;
  padding: 60px 0;
}

.compliance-cta h2 { margin-bottom: 12px; }
.compliance-cta p { max-width: 600px; margin: 0 auto 28px; }

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0;
  margin-top: 48px;
  flex-wrap: wrap;
}

.lifecycle-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 20px 16px;
  position: relative;
  min-width: 120px;
}

.lifecycle-step__circle {
  width: 72px; height: 72px;
  border-radius: 50%;
  background: rgba(0,180,216,0.12);
  border: 2px solid var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 12px;
  transition: all var(--transition);
}
.lifecycle-step:hover .lifecycle-step__circle { background: var(--accent); color: var(--navy); }

.lifecycle-step__label { font-size: 0.82rem; font-weight: 600; color: var(--gray-light); }

.lifecycle-arrow {
  color: var(--accent);
  font-size: 1.5rem;
  padding: 0 8px;
  opacity: 0.5;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: var(--navy-mid);
  border-top: 1px solid rgba(255,255,255,0.08);
  padding: 20px 0;
  z-index: 2000;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { transform: translateY(100%); }

.cookie-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner__text { font-size: 0.88rem; color: var(--gray-light); }
.cookie-banner__actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ===== FOOTER ===== */
.footer {
  background: var(--brand);
  padding: 60px 0 30px;
  border-top: 1px solid rgba(255,255,255,0.05);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 32px;
}

.footer__brand p { font-size: 0.85rem; color: var(--gray-mid); margin-top: 12px; line-height: 1.6; }

.footer__col h4 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-light);
  margin-bottom: 16px;
}

.footer__link {
  display: block;
  font-size: 0.85rem;
  color: var(--gray-mid);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer__link:hover { color: var(--accent); }

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.06);
  font-size: 0.8rem;
  color: var(--gray-mid);
}

.footer__login-links { display: flex; gap: 20px; }

/* ===== SVG DIAGRAM ICONS ===== */
.icon-svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .use-cases__grid { grid-template-columns: repeat(2, 1fr); }
  .stats__grid { grid-template-columns: repeat(3, 1fr); gap: 20px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .integration-panel { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .section { padding: 56px 0; }
  .hero { padding: 110px 0 56px; }

  .nav { display: none; }
  .nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px; left: 0; right: 0;
    background: var(--navy-mid);
    padding: 20px 24px;
    gap: 16px;
    border-bottom: 1px solid rgba(255,255,255,0.06);
  }
  .nav__toggle { display: block; }

  .nav__dropdown-menu {
    position: static;
    transform: none;
    opacity: 1;
    visibility: visible;
    box-shadow: none;
    border: none;
    padding-left: 16px;
  }

  .use-cases__grid { grid-template-columns: 1fr; }
  .stats__grid { grid-template-columns: 1fr; gap: 32px; }
  .benefits__grid { grid-template-columns: repeat(2, 1fr); }
  .etl-benefits__grid { grid-template-columns: 1fr; }
  .support-regions { grid-template-columns: 1fr; }

  .featured-banner__inner { flex-direction: column; text-align: center; }

  .culture__inner, .renewables__inner { flex-direction: column; text-align: center; }

  .demo-form__grid { grid-template-columns: 1fr; }

  .footer__grid { grid-template-columns: repeat(2, 1fr); }

  .diagram { flex-direction: column; align-items: center; }
  .diagram__connector { transform: rotate(90deg); }

  .lifecycle-diagram { flex-direction: column; }
  .lifecycle-arrow { transform: rotate(90deg); }

  .cookie-banner__inner { flex-direction: column; text-align: center; }
}

@media (max-width: 480px) {
  .benefits__grid { grid-template-columns: 1fr; }
  .footer__grid { grid-template-columns: 1fr; }
  .hero__actions { flex-direction: column; }
  .hero__actions .btn { width: 100%; justify-content: center; }
}

raw_arguments.content:
/* ===== RESET & BASE ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-light: #243447;
  --brand: #15295A;
  --accent: #00B4D8;
  --accent-dark: #0077B6;
  --green: #6CC24A;
  --gray-dark: #3C424B;
  --gray-mid: #8892A0;
  --gray-light: #B0B8C4;
  --white: #FFFFFF;
  --off-white: #E8ECF1;
  --font: 'Inter', system-ui, -apple-system, sans-serif;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 4px 24px rgba(0,0,0,0.3);
  --transition: 0.3s ease;
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font);
  background: var(--navy);
  color: var(--off-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--accent); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--white); }

img { max-width: 100%; display: block; }

/* ===== UTILITY ===== */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.section { padding: 80px 0; }
.section--alt { background: var(--navy-mid); }
.text-center { text-align: center; }
.text-accent { color: var(--accent); }
.text-green { color: var(--green); }

.label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent);
  margin-bottom: 12px;
}

h1, h2, h3, h4 { font-weight: 700; line-height: 1.2; color: var(--white); }
h1 { font-size: clamp(2rem, 5vw, 3.25rem); }
h2 { font-size: clamp(1.75rem, 4vw, 2.5rem); margin-bottom: 16px; }
h3 { font-size: 1.25rem; margin-bottom: 8px; }
p { color: var(--gray-light); }

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 28px;
  border: none;
  border-radius: var(--radius);
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: all var(--transition);
  text-decoration: none;
}

.btn--primary {
  background: var(--accent);
  color: var(--navy);
}
.btn--primary:hover { background: #33C9E8; color: var(--navy); }

.btn--outline {
  background: transparent;
  color: var(--accent);
  border: 2px solid var(--accent);
}
.btn--outline:hover { background: var(--accent); color: var(--navy); }

.btn--green { background: var(--green); color: var(--navy); }
.btn--green:hover { background: #7DD45B; color: var(--navy); }

.btn--sm { padding: 10px 20px; font-size: 0.85rem; }

/* ===== HEADER / NAV ===== */
.header {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  background: rgba(13,27,42,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}

.header__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.header__logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--white);
  letter-spacing: -0.02em;
}
.header__logo span { color: var(--accent); }

.nav { display: flex; align-items: center; gap: 32px; }

.nav__link {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-light);
  position: relative;
}
.nav__link:hover { color: var(--white); }

/* Dropdown */
.nav__dropdown { position: relative; }
.nav__dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--gray-light);
  cursor: pointer;
  background: none;
  border: none;
  font-family: var(--font);
}
.nav__dropdown-toggle:hover { color: var(--white); }
.nav__dropdown-toggle svg { width: 12px; height: 12px; transition: transform var(--transition); }

.nav__dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: var(--radius);
  padding: 8px 0;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  box-shadow: var(--shadow);
}
.nav__dropdown:hover .nav__dropdown-menu { opacity: 1; visibility: visible; }
.nav__dropdown:hover .nav__dropdown-toggle svg { transform: rotate(180deg); }

.nav__dropdown-item {
  display: block;
  padding: 10px 20px;
  font-size: 0.85rem;
  color: var(--gray-light);
  transition: all var(--transition);
}
.nav__dropdown-item:hover { background: var(--navy-light); color: var(--white); }

/* Mobile nav toggle */
.nav__toggle { display: none; background: none; border: none; cursor: pointer; padding: 8px; }
.nav__toggle span { display: block; width: 24px; height: 2px; background: var(--white); margin: 5px 0; transition: var(--transition); }

/* ===== HERO ===== */
.hero {
  padding: 140px 0 80px;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -40%; right: -20%;
  width: 800px; height: 800px;
  background: radial-gradient(circle, rgba(0,180,216,0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content { max-width: 720px; position: relative; z-index: 1; }
.hero__title { margin-bottom: 20px; }
.hero__subtitle { font-size: 1.15rem; margin-bottom: 32px; color: var(--gray-light); line-height: 1.7; }
.hero__actions { display: flex; gap: 16px; flex-wrap: wrap; }

.hero--centered { text-align: center; }
.hero--centered .hero__content { max-width: 800px; margin: 0 auto; }
.hero--centered .hero__actions { justify-content: center; }

/* ===== FEATURED BANNER ===== */
.featured-banner {
  padding: 40px 0;
  background: linear-gradient(135deg, var(--brand) 0%, var(--navy-light) 100%);
  border-top: 1px solid rgba(255,255,255,0.05);
  border-bottom: 1px solid rgba(255,255,255,0.05);
}

.featured-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.featured-banner__text h3 { font-size: 1.1rem; }
.featured-banner__text p { font-size: 0.9rem; color: var(--gray-mid); }
.featured-banner__badge {
  display: inline-block;
  background: var(--accent);
  color: var(--navy);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  margin-bottom: 6px;
}

/* ===== USE CASES ===== */
.use-cases__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.use-case-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: all var(--transition);
  cursor: pointer;
}
.use-case-card:hover {
  border-color: var(--accent);
  transform: translateY(-4px);
  box-shadow: 0 8px 32px rgba(0,180,216,0.12);
}

.use-case-card__icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--accent);
  font-size: 1.4rem;
}

.use-case-card h3 { font-size: 1.05rem; margin-bottom: 8px; }
.use-case-card p { font-size: 0.88rem; color: var(--gray-mid); line-height: 1.6; }

/* ===== TABS ===== */
.tabs { margin-top: 32px; }

.tabs__nav {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid rgba(255,255,255,0.08);
  margin-bottom: 32px;
  overflow-x: auto;
}

.tabs__tab {
  padding: 12px 24px;
  font-family: var(--font);
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--gray-mid);
  background: none;
  border: none;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}
.tabs__tab:hover { color: var(--white); }
.tabs__tab.active { color: var(--accent); border-bottom-color: var(--accent); }

.tabs__panel { display: none; }
.tabs__panel.active { display: block; animation: fadeIn 0.3s ease; }

@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* ===== PLATFORM DIAGRAM ===== */
.diagram {
  display: flex;
  justify-content: center;
  gap: 32px;
  flex-wrap: wrap;
  margin-top: 48px;
}

.diagram__pillar {
  flex: 1;
  min-width: 280px;
  max-width: 360px;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}
.diagram__pillar:hover { border-color: var(--accent); }

.diagram__pillar-icon {
  width: 64px; height: 64px;
  margin: 0 auto 16px;
  background: rgba(0,180,216,0.12);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.6rem;
}

.diagram__pillar h3 { margin-bottom: 8px; }
.diagram__pillar p { font-size: 0.88rem; color: var(--gray-mid); }

.diagram__connector {
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.5rem;
  min-width: 40px;
}

/* ===== STATS ===== */
.stats__grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}

.stat {
  text-align: center;
}

.stat__circle {
  width: 160px; height: 160px;
  margin: 0 auto 20px;
  position: relative;
}

.stat__circle svg {
  width: 100%; height: 100%;
  transform: rotate(-90deg);
}

.stat__circle-bg {
  fill: none;
  stroke: rgba(255,255,255,0.06);
  stroke-width: 8;
}

.stat__circle-fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 8;
  stroke-linecap: round;
  stroke-dasharray: 440;
  stroke-dashoffset: 440;
  transition: stroke-dashoffset 1.5s ease;
}

.stat__circle-value {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  font-size: 2.2rem;
  font-weight: 800;
  color: var(--white);
}

.stat p { font-size: 0.9rem; color: var(--gray-mid); max-width: 200px; margin: 0 auto; }

/* ===== BENEFITS ===== */
.benefits__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
  margin-top: 40px;
}

.benefit-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
  transition: all var(--transition);
}
.benefit-card:hover { border-color: var(--accent); transform: translateY(-2px); }

.benefit-card__icon {
  width: 48px; height: 48px;
  margin: 0 auto 14px;
  background: rgba(0,180,216,0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.2rem;
}

.benefit-card h3 { font-size: 1rem; margin-bottom: 6px; }
.benefit-card p { font-size: 0.85rem; color: var(--gray-mid); }

/* ===== IMPLEMENTATION TIMELINE ===== */
.timeline { margin-top: 40px; }

.timeline__item {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  padding: 24px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.timeline__item:last-child { border-bottom: none; }

.timeline__duration {
  min-width: 120px;
  text-align: right;
}
.timeline__duration strong {
  display: block;
  font-size: 1.3rem;
  color: var(--accent);
}

.timeline__bar-wrap { flex: 1; }
.timeline__bar-track {
  width: 100%;
  height: 8px;
  background: rgba(255,255,255,0.06);
  border-radius: 4px;
  margin: 8px 0;
}
.timeline__bar-fill {
  height: 100%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--accent), var(--accent-dark));
  transition: width 1s ease;
}

.timeline__label { font-size: 0.9rem; color: var(--gray-light); }

/* ===== ACCORDION ===== */
.accordion { margin-top: 40px; }

.accordion__item {
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius);
  margin-bottom: 8px;
  overflow: hidden;
  transition: border-color var(--transition);
}
.accordion__item.open { border-color: var(--accent); }

.accordion__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  background: var(--navy-mid);
  cursor: pointer;
  border: none;
  width: 100%;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  color: var(--white);
  text-align: left;
  transition: background var(--transition);
}
.accordion__header:hover { background: var(--navy-light); }

.accordion__icon {
  width: 24px; height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  transition: transform var(--transition);
  font-size: 1.2rem;
  flex-shrink: 0;
}
.accordion__item.open .accordion__icon { transform: rotate(45deg); }

.accordion__body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
  background: var(--navy-mid);
}
.accordion__item.open .accordion__body { max-height: 300px; }

.accordion__content { padding: 0 24px 20px; color: var(--gray-light); font-size: 0.92rem; line-height: 1.7; }

/* ===== TESTIMONIAL CAROUSEL ===== */
.carousel { margin-top: 40px; position: relative; overflow: hidden; }

.carousel__track {
  display: flex;
  transition: transform 0.5s ease;
}

.carousel__slide {
  min-width: 100%;
  padding: 0 16px;
}

.testimonial-card {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 40px;
  position: relative;
}

.testimonial-card__quote {
  font-size: 1.1rem;
  font-style: italic;
  color: var(--off-white);
  line-height: 1.7;
  margin-bottom: 20px;
}

.testimonial-card__quote::before {
  content: '\201C';
  font-size: 3rem;
  color: var(--accent);
  line-height: 0;
  vertical-align: -0.4em;
  margin-right: 4px;
}

.testimonial-card__author { font-size: 0.9rem; color: var(--gray-mid); }

.carousel__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel__dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: rgba(255,255,255,0.15);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}
.carousel__dot.active { background: var(--accent); transform: scale(1.2); }

/* ===== SECURITY FEATURES ===== */
.security-features { margin-top: 40px; }

.security-feature {
  display: flex;
  gap: 20px;
  padding: 28px 0;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  align-items: flex-start;
}
.security-feature:last-child { border-bottom: none; }

.security-feature__icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.2rem;
  flex-shrink: 0;
}

.security-feature__text h3 { font-size: 1.05rem; margin-bottom: 4px; }
.security-feature__text p { font-size: 0.9rem; color: var(--gray-mid); line-height: 1.6; }

/* ===== INTEGRATION TABS ===== */
.integration-panel {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  align-items: start;
}

.integration-panel__visual {
  background: var(--navy-light);
  border-radius: var(--radius-lg);
  padding: 40px;
  min-height: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.integration-panel__content h3 { margin-bottom: 12px; }
.integration-panel__content p { margin-bottom: 16px; line-height: 1.7; }

/* ===== ETL BENEFITS ===== */
.etl-benefits__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 40px;
}

.etl-benefit {
  display: flex;
  gap: 16px;
  padding: 24px;
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  align-items: flex-start;
  transition: all var(--transition);
}
.etl-benefit:hover { border-color: var(--green); }

.etl-benefit__check {
  width: 28px; height: 28px;
  background: rgba(108,194,74,0.15);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--green);
  font-size: 0.85rem;
  flex-shrink: 0;
}

.etl-benefit h3 { font-size: 0.95rem; margin-bottom: 4px; }
.etl-benefit p { font-size: 0.85rem; color: var(--gray-mid); }

/* ===== DEMO FORM ===== */
.demo-form { max-width: 680px; margin: 0 auto; }

.demo-form__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-top: 32px;
}

.form-group { display: flex; flex-direction: column; }
.form-group--full { grid-column: 1 / -1; }

.form-group label {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--gray-light);
  margin-bottom: 6px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.form-group input,
.form-group select,
.form-group textarea {
  padding: 12px 16px;
  background: var(--navy-light);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius);
  color: var(--white);
  font-family: var(--font);
  font-size: 0.95rem;
  transition: border-color var(--transition);
}
.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--accent);
}

.form-group textarea { resize: vertical; min-height: 100px; }

.form-group .error-msg {
  font-size: 0.78rem;
  color: #E74C3C;
  margin-top: 4px;
  display: none;
}
.form-group.has-error .error-msg { display: block; }
.form-group.has-error input,
.form-group.has-error select,
.form-group.has-error textarea { border-color: #E74C3C; }

.demo-form__submit { margin-top: 28px; text-align: center; }

/* ===== SUPPORT CONTACT ===== */
.support-regions {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 32px;
}

.support-region {
  background: var(--navy-mid);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
}
.support-region h3 { font-size: 1rem; margin-bottom: 8px; }
.support-region p { font-size: 0.88rem; color: var(--gray-mid); }

/* ===== COMPANY CULTURE ===== */
.culture {
  background: linear-gradient(135deg, var(--brand) 0%, var(--navy) 100%);
}

.culture__inner {
  display: flex;
  align-items: center;
  gap: 48px;
}

.culture__content { flex: 1; }
.culture__content p { font-size: 1rem; line-height: 1.7; margin-bottom: 24px; }

.culture__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

.culture__number {
  font-size: 6rem;
  font-weight: 900;
  color: var(--accent);
  line-height: 1;
  opacity: 0.2;
}
.culture__number span { font-size: 1.5rem; display: block; font-weight: 600; opacity: 1; color: var(--gray-light); }

/* ===== RENEWABLES CTA ===== */
.renewables {
  background: linear-gradient(135deg, #0a2a1a 0%, var(--navy) 100%);
}

.renewables__inner {
  display: flex;
  align-items: center;
  gap: 48px;
}

.renewables__content { flex: 1; }
.renewables__content p { font-size: 1rem; line-height: 1.7; margin-bottom: 24px; }

.renewables__visual {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
}

/* ===== COMPLIANCE CTA ===== */
.compliance-cta {
  text-align: center;
  padding: 60px 0;
}

.compliance-cta h2 { margin-bottom: 12px; }
.compliance-cta p { max-width: 600px; margin: 0 auto 28px; }

/* ===== DATA LIFECYCLE DIAGRAM ===== */
.lifecycle-diagram {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0;
  margin-top: 48px;
  flex-wrap: wrap;
}

.lifecycle-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 20px 16px;
  position: relative;
  min-width: 120px;
}

.lifecycle-step__circle {
  width: 72px; height: 72px;
  border-radius: 50%;
  background: rgba(0,180,216,0.12);
  border: 2px solid var(--accent);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--accent);
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 12px;
  transition: all var(--transition);
}
.lifecycle-step:hover .lifecycle-step__circle { background: var(--accent); color: var(--navy); }

.lifecycle-step__label { font-size: 0.82rem; font-weight: 600; color: var(--gray-light); }

.lifecycle-arrow {
  color: var(--accent);
  font-size: 1.5rem;
  padding: 0 8px;
  opacity: 0.5;
}

/* ===== COOKIE BANNER ===== */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: var(--navy-mid);
  border-top: 1px solid rgba(255,255,255,0.08);
  padding: 20px 0;
  z-index: 2000;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-banner.hidden { transform: translateY(100%); }

.cookie-banner__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-banner__text { font-size: 0.88rem; color: var(--gray-light); }
.cookie-banner__actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ===== FOOTER ===== */
.footer {
  background: var(--brand);
  padding: 60px 0 30px;
  border-top: 1px solid rgba(255,255,255,0.05);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 32px;
}

.footer__brand p { font-size: 0.85rem; color: var(--gray-mid); margin-top: 12px; line-height: 1.6; }

.footer__col h4 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-light);
  margin-bottom: 16px;
}

.footer__link {
  display: block;
  font-size: 0.85rem;
  color: var(--gray-mid);
  padding: 4px 0;
  transition: color var(--transition);
}
.footer__link:hover { color: var(--accent); }

.footer__bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 40px;
  padding-top: 20px;
  border-top: 1px solid rgba(255,255,255,0.06);
  font-size: 0.8rem;
  color: var(--gray-mid);
}

.footer__login-links { display: flex; gap: 20px; }

/* ===== SVG DIAGRAM ICONS ===== */
.icon-svg { width: 24px; height: 24px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* ===== RESPONSIVE ===== */
@media (max-width: 1024px) {
  .use-cases__grid { grid-template-columns: repeat(2, 1fr); }
  .stats__grid { grid-template-columns: repeat(3, 1fr); gap: 20px; }
  .footer__grid { grid-template-columns: repeat(3, 1fr); }
  .integration-panel { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  .section { padding: 56px 0; }
  .hero { padding: 110px 0 56px; }

  .nav { display: none; }
  .nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 72px; left: 0; right: 0;
